	private static void runTrial(ThemeQueryBenchmark benchmark) throws IOException {
		benchmark.setup();
		benchmark.tearDown();
	}

	private static Properties readMetadata(Path directory) throws IOException {
		Properties properties = new Properties();
		try (var input = Files.newInputStream(directory.resolve(METADATA_FILE))) {
			properties.load(input);
		}
		return properties;
	}

	private static void withFixtureConnection(Path directory, Consumer<SailRepositoryConnection> operation) {
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(),
				ThemeQueryBenchmark.ConfigUtil.createConfig()));
		try (var connection = repository.getConnection()) {
			operation.accept(connection);
		} finally {
			repository.shutDown();
		}
	}

	private static void restoreProperty(String property, String previousValue) {
		if (previousValue == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, previousValue);
		}
	}

	private static ThemeQueryBenchmark fixtureBenchmark(Path directory, int[] loads) {
		ThemeQueryBenchmark benchmark = new ThemeQueryBenchmark(directory.toFile(), repository -> {
			loads[0]++;
			try (var connection = repository.getConnection()) {
				connection.begin();
				for (int statement = 0; statement < 128; statement++) {
					connection.add(Values.iri("urn:subject:" + statement), Values.iri("urn:predicate"),
							Values.literal("fixture-value-" + statement), Values.iri("urn:graph:" + statement % 2));
				}
				connection.commit();
			}
		});
		configureFixture(benchmark);
		return benchmark;
	}

	private static void configureFixture(ThemeQueryBenchmark benchmark) {
		benchmark.themeName = "MEDICAL_RECORDS";
		benchmark.z_queryIndex = 0;
		benchmark.z_z_irMode = "disabled";
	}
